func (e ListVoiceVerificationParamsLevel) Valid() bool {
	switch e {
	case ListVoiceVerificationParamsLevelAll:
		return true
	case ListVoiceVerificationParamsLevelAmbiguous:
		return true
	case ListVoiceVerificationParamsLevelUnknown:
		return true
	default:
		return false
	}
}

